window.__TNPSC_REGISTER_TEST__("tamil", 9, [{"id":801,"subject":"tamil","testNumber":9,"question":"மகாகவி பாரதியார் பிறந்த ஊர் மற்றும் அவரது பெற்றோர் பெயர்களைச் சரியாகத் தேர்ந்தெடுக்கவும்.","options":["மோகனூர்; வெங்கடராமன் – அம்மணி அம்மாள்","தேரூர்; சிவதாணுப் பிள்ளை – ஆதிலட்சுமி அம்மாள்","எட்டயபுரம்; சின்னசாமி ஐயர் – இலக்குமி அம்மாள்","திருநெல்வேலி; கனகசபை – இலக்குமி அம்மாள்"],"correctAnswer":2,"explanation":"மகாகவி பாரதியார் 1882-ஆம் ஆண்டு டிசம்பர் 11-ஆம் நாள் தூத்துக்குடி மாவட்டத்தில் உள்ள எட்டயபுரத்தில் பிறந்தார். இவரது இயற்பெயர் சுப்பிரமணியன்; பெற்றோர் சின்னசாமி ஐயர் மற்றும் இலக்குமி அம்மாள் ஆவர்.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":802,"subject":"tamil","testNumber":9,"question":"சுப்பிரமணியன் என்ற இயற்பெயர் கொண்ட பாரதியாருக்குத் தனது பதினோராம் வயதில் 'பாரதி' என்ற பட்டம் எங்கு வழங்கப்பட்டது?","options":["மதுரைத் தமிழ்ச் சங்க அவையில்","புதுக்கோட்டை சமஸ்தான அவையில்","தஞ்சாவூர் சரஸ்வதி மகால் அவையில்","எட்டயபுரம் மன்னர் அவையில்"],"correctAnswer":3,"explanation":"இளமையிலேயே கவிபாடும் ஆற்றல் பெற்ற சுப்பிரமணியனுக்குத் தமது பதினோராம் வயதில் எட்டயபுரம் மன்னர் அவையில் இருந்த புலவர்களால் 'பாரதி' (கலைமகள்) என்ற பட்டம் வழங்கப்பட்டது.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":803,"subject":"tamil","testNumber":9,"question":"பாரதியார் தமது புரட்சிகரமான விடுதலைக் கருத்துகளை வெளிப்படுத்தச் சிவப்புத் தாளில் அச்சிட்டு வெளியிட்ட வார இதழ் எது?","options":["இந்தியா","சுதேசமித்திரன்","கர்மயோகி","சக்கரவர்த்தினி"],"correctAnswer":0,"explanation":"பாரதியார் 1906-ஆம் ஆண்டு 'இந்தியா' என்ற வார இதழின் ஆசிரியராகப் பொறுப்பேற்றார். புரட்சியின் அடையாளமாக இவ்விதழைச் சிவப்புத் தாளில் அச்சிட்டு வெளியிட்டதோடு தமிழில் முதன்முதலாகக் கருத்துப்படங்களை (கேலிச்சித்திரங்கள்) அறிமுகப்படுத்தினார்.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":804,"subject":"tamil","testNumber":9,"question":"பெண்களின் முன்னேற்றத்திற்காகப் பாரதியார் ஆசிரியராகப் பணியாற்றிய மகளிர் மாத இதழ் எது?","options":["சக்கரவர்த்தினி","பாலபாரதம்","விஜயா","சூரியோதயம்"],"correctAnswer":0,"explanation":"மகாகவி பாரதியார் 1905-ஆம் ஆண்டு 'சக்கரவர்த்தினி' என்ற மகளிர் மாத இதழின் ஆசிரியராகப் பணியாற்றினார். இதன் மூலம் பெண் விடுதலை, பெண் கல்வி குறித்த சிந்தனைகளைப் பரப்பினார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":805,"subject":"tamil","testNumber":9,"question":"1904-ஆம் ஆண்டு மதுரை சேதுபதி உயர்நிலைப் பள்ளியில் தமிழாசிரியராகப் பணியாற்றிய பின் பாரதியார் துணை ஆசிரியராகச் சேர்ந்த நாளிதழ் எது?","options":["குடியரசு","தேசபக்தன்","சுதேசமித்திரன்","நவசக்தி"],"correctAnswer":2,"explanation":"பாரதியார் 1904-இல் மதுரை சேதுபதி உயர்நிலைப் பள்ளியில் சில மாதங்கள் தமிழாசிரியராகப் பணியாற்றினார். அதன்பின் ஜி.சுப்பிரமணிய ஐயரின் அழைப்பின் பேரில் 'சுதேசமித்திரன்' இதழில் துணை ஆசிரியராகச் சேர்ந்தார்.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":806,"subject":"tamil","testNumber":9,"question":"பின்வருவனவற்றுள் பாரதியார் ஆசிரியராக இருந்த ஆங்கில இதழ் மற்றும் புதுச்சேரியிலிருந்து நடத்திய நாளிதழ் ஆகியவற்றின் சரியான இணை எது?","options":["பாலபாரதம் – விஜயா","நியூ இந்தியா – கர்மயோகி","காமன்வீல் – சக்கரவர்த்தினி","யங் இந்தியா – சுதேசமித்திரன்"],"correctAnswer":0,"explanation":"பாரதியார் 'பாலபாரதம்' என்ற ஆங்கில இதழை நடத்தியதோடு, ஆங்கிலேய அடக்குமுறையிலிருந்து தப்பிப் புதுச்சேரியில் தங்கியிருந்தபோது 'விஜயா' என்ற தமிழ் நாளிதழையும் வெளியிட்டார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":807,"subject":"tamil","testNumber":9,"question":"பாரதியாரின் 'முப்பெரும் பாடல்கள்' எனப் போற்றப்படும் படைப்புகள் யாவை?","options":["பாப்பாப் பாட்டு, புதிய ஆத்திசூடி, விநாயகர் நான்மணிமாலை","கண்ணன் பாட்டு, குயில் பாட்டு, பாஞ்சாலி சபதம்","சுதேச கீதங்கள், ஜன்மபூமி, மதாந்திரப் பாடல்கள்","ஞானரதம், தராசு, சந்திரிகையின் கதை"],"correctAnswer":1,"explanation":"பாரதியார் புதுச்சேரியில் தங்கியிருந்த காலத்தில் (1912-ஆம் ஆண்டு) படைத்த கண்ணன் பாட்டு, குயில் பாட்டு, பாஞ்சாலி சபதம் ஆகிய மூன்றும் அவரது 'முப்பெரும் பாடல்கள்' எனத் தமிழிலக்கிய உலகில் போற்றப்படுகின்றன.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":808,"subject":"tamil","testNumber":9,"question":"வியாச பாரதத்தைத் தழுவிப் பாரதியார் இயற்றிய 'பாஞ்சாலி சபதம்' எத்தனை பாகங்கள், சருக்கங்கள் மற்றும் பாடல்களைக் கொண்டது?","options":["2 பாகங்கள், 4 சருக்கங்கள், 360 பாடல்கள்","4 பாகங்கள், 5 சருக்கங்கள், 420 பாடல்கள்","3 பாகங்கள், 6 சருக்கங்கள், 500 பாடல்கள்","2 பாகங்கள், 5 சருக்கங்கள், 412 பாடல்கள்"],"correctAnswer":3,"explanation":"பாஞ்சாலி சபதம் இரண்டு பாகங்களையும், ஐந்து சருக்கங்களையும் (சூழ்ச்சிச் சருக்கம், சூதாட்டச் சருக்கம், அடிமைச் சருக்கம், துகிலுரிதல் சருக்கம், சபதச் சருக்கம்), 412 பாடல்களையும் கொண்ட எளிய சந்தக் காப்பியமாகும்.","difficulty":"hard","topic":"மகாகவி பாரதியார்"},{"id":809,"subject":"tamil","testNumber":9,"question":"'கண்ணன் பாட்டு' என்னும் நூலில் பாரதியார் கண்ணனைத் தோழன், தாய், தந்தை, சேவகன், குழந்தை முதலிய எத்தனை நிலைகளில் பாடியுள்ளார்?","options":["23 நிலைகள்","27 நிலைகள்","12 நிலைகள்","18 நிலைகள்"],"correctAnswer":0,"explanation":"கண்ணன் பாட்டில் பாரதியார் கண்ணனைத் தோழன், தாய், தந்தை, சேவகன், அரசன், சீடன், சற்குரு, கண்ணம்மா என் குழந்தை, காதலி, காதலன், குலதெய்வம் என 23 பாடல்களில் 23 வகையான உறவு நிலைகளில் போற்றிப் பாடியுள்ளார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":810,"subject":"tamil","testNumber":9,"question":"பாரதியாரின் 'குயில் பாட்டு' பற்றிய பின்வரும் கூற்றுகளில் சரியானது எது?","options":["இது குழந்தைகளுக்காக எளிய ஒற்றை வரிகளில் எழுதப்பட்ட நீதிநூல்","இது மகாபாரதக் கிளைக்கதையைத் தழுவி எழுதப்பட்ட வரலாற்றுக் காப்பியம்","இது பாரதியார் எழுதிய முற்றுப்பெறாத சமூகப் புதினம்","இது புதுச்சேரி மாஞ்சோலையைக் களமாகக் கொண்டு எழுதப்பட்ட கற்பனைக் காவியம்"],"correctAnswer":3,"explanation":"குயில் பாட்டு என்பது பாரதியார் புதுச்சேரியில் உள்ள ஒரு மாஞ்சோலையைப் பின்னணியாகக் கொண்டு படைத்த அழகிய கற்பனைக் காவியம் (உருவகக் காவியம்) ஆகும். இதில் குயில், குரங்கு, மாடு ஆகிய பாத்திரங்கள் இசை, காதல் மற்றும் வேதாந்தக் கருத்துகளை உணர்த்துகின்றன.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":811,"subject":"tamil","testNumber":9,"question":"பாரதியார் இயற்றிய 'புதிய ஆத்திசூடி' எந்தத் தொடருடன் தொடங்குகிறது?","options":["உடலினை உறுதி செய்","ஆண்மை தவறேல்","அச்சம் தவிர்","அறம் செய விரும்பு"],"correctAnswer":2,"explanation":"ஔவையாரின் ஆத்திசூடி 'அறம் செய விரும்பு' எனத் தொடங்க, தற்கால இளைய தலைமுறையினருக்குத் துணிவூட்டும் வகையில் பாரதியார் இயற்றிய 'புதிய ஆத்திசூடி' 'அச்சம் தவிர்' என்ற தொடருடன் தொடங்குகிறது.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":812,"subject":"tamil","testNumber":9,"question":"\"சொல்லில் உயர்வு தமிழ்ச்சொல்லே – அதைத் தொழுது படித்திடடி பாப்பா\" என்ற வரிகள் பாரதியாரின் எந்தப் பாடலில் இடம்பெற்றுள்ளன?","options":["தமிழ்த்தாய் பாடல்","பாப்பாப் பாட்டு","புதிய ஆத்திசூடி","கண்ணம்மா என் குழந்தை"],"correctAnswer":1,"explanation":"'ஓடி விளையாடு பாப்பா' எனத் தொடங்கும் பாரதியாரின் 'பாப்பாப் பாட்டு' குழந்தைகளுக்குத் தமிழ்மொழிப் பற்று, அன்பு, சாதி மறுப்பு மற்றும் ஒழுக்கத்தை உணர்த்துகின்றது. அதில் 'சொல்லில் உயர்வு தமிழ்ச்சொல்லே' என்ற புகழ்பெற்ற வரி இடம்பெற்றுள்ளது.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":813,"subject":"tamil","testNumber":9,"question":"தமிழில் 'வசன கவிதை' என்னும் புதிய இலக்கிய வடிவத்தைத் தொடங்கி வைத்தவர் யார்?","options":["ந.பிச்சமூர்த்தி","கவிமணி தேசிக விநாயகம் பிள்ளை","பாரதிதாசன்","மகாகவி பாரதியார்"],"correctAnswer":3,"explanation":"உரைநடையும் கவிதையும் இணைந்து யாப்புக் கட்டுகளுக்கு அப்பாற்பட்டு உருவாக்கப்படும் 'வசன கவிதை'யைத் தமிழில் முதன்முதலில் அறிமுகப்படுத்தியவர் மகாகவி பாரதியார் ஆவார். ஞாயிறு, காற்று, சக்தி, கடல் ஆகிய தலைப்புகளில் அவர் வசன கவிதைகளைப் படைத்துள்ளார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":814,"subject":"tamil","testNumber":9,"question":"பின்வருவனவற்றுள் பாரதியார் எழுதிய உரைநடை நூல்களின் தொகுப்பு எது?","options":["மலைக்கள்ளன், என் கதை, சங்கொலி","வாடிவாசல், சுதந்திர தாகம், ஜீவனாம்சம்","வனவாசம், மனவாசம், சேரமான் காதலி","ஞானரதம், சந்திரிகையின் கதை, தராசு"],"correctAnswer":3,"explanation":"ஞானரதம் (கற்பனை உரைநடைக் காவியம்), சந்திரிகையின் கதை (முற்றுப்பெறாத புதினம்), தராசு ஆகிய மூன்றும் மகாகவி பாரதியார் எழுதிய புகழ்பெற்ற உரைநடைப் படைப்புகள் ஆகும்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":815,"subject":"tamil","testNumber":9,"question":"\"சிந்துக்குத் தந்தை\", \"நீடுதுயில் நீக்கப் பாடிவந்த நிலா\", \"மறம் பாட வந்த மறவன்\" என்றெல்லாம் பாரதியாரைப் புகழ்ந்தவர் யார்?","options":["வ.உ.சிதம்பரனார்","நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்","பாவேந்தர் பாரதிதாசன்","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":2,"explanation":"பாரதியாரின் கவித்திறனைப் போற்றிப் பாவேந்தர் பாரதிதாசன் அவரை 'சிந்துக்குத் தந்தை', 'செந்தமிழ்த் தேனீ', 'புதிய அறம் பாட வந்த அறிஞன்', 'மறம் பாட வந்த மறவன்', 'நீடுதுயில் நீக்கப் பாடிவந்த நிலா' எனப் பலவாறு பாராட்டியுள்ளார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":816,"subject":"tamil","testNumber":9,"question":"\"பாட்டுக்கொரு புலவன் பாரதியடா – அவன் பாட்டைப் பண்ணோடு ஒருவன் பாடினானடா\" எனப் பாரதியாரைப் போற்றிய கவிஞர் யார்?","options":["சுரதா","வாணிதாசன்","நாமக்கல் கவிஞர்","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":3,"explanation":"'பாட்டுக்கொரு புலவன் பாரதி' என்று மகாகவி பாரதியாரைப் போற்றிப் பாடியவர் கவிமணி தேசிக விநாயகம் பிள்ளை ஆவார். இந்தப் புகழாரம் 'மலரும் மாலையும்' நூலில் இடம்பெற்றுள்ளது.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":817,"subject":"tamil","testNumber":9,"question":"\"தனியொருவனுக்கு உணவில்லையெனில் ஜகத்தினை அழித்திடுவோம்\" என்ற முழக்கத்தைப் பாரதியார் தமது எந்தப் பாடலில் பதிவு செய்துள்ளார்?","options":["விடுதலை","பாரத சமுதாயம்","வந்தே மாதரம்","சுதந்திரப் பள்ளு"],"correctAnswer":1,"explanation":"'பாரத சமுதாயம் வாழ்கவே' என்ற பாடலில் அனைவருக்கும் சம உரிமையும் உணவும் கிடைக்க வேண்டும் என்ற உயரிய சமுதாயச் சிந்தனையாக 'தனியொருவனுக்கு உணவில்லையெனில் ஜகத்தினை அழித்திடுவோம்' என்று பாரதியார் பாடியுள்ளார்.","difficulty":"medium","topic":"மகாகவி பாரதியார்"},{"id":818,"subject":"tamil","testNumber":9,"question":"\"சென்றிடுவீர் எட்டுத் திக்கும் – கலைச் செல்வங்கள் யாவும் கொணர்ந்திங்கு சேர்ப்பீர்\" என்ற பாரதியாரின் வரி எதை வலியுறுத்துகிறது?","options":["பிறநாட்டு அறிவியல் மற்றும் கலைச் செல்வங்களைத் தமிழில் கொண்டுவருதல்","பிறமொழிகளைப் புறக்கணித்தல்","பண்டைய இலக்கணங்களை மட்டும் பாதுகாத்தல்","வாணிகம் மூலம் பொன் சேர்த்தல்"],"correctAnswer":0,"explanation":"உலகின் அனைத்துத் திசைகளிலும் உள்ள அறிவியல், கலை மற்றும் இலக்கியச் செல்வங்களைத் தமிழ்மொழியில் மொழிபெயர்த்து வளப்படுத்த வேண்டும் என்பதையே பாரதியார் 'சென்றிடுவீர் எட்டுத் திக்கும்' என்ற வரிகளால் வலியுறுத்துகிறார்.","difficulty":"easy","topic":"மகாகவி பாரதியார்"},{"id":819,"subject":"tamil","testNumber":9,"question":"1904-ஆம் ஆண்டு 'விவேகபானு' என்னும் இதழில் அச்சில் வெளிவந்த பாரதியாரின் முதல் பாடல் எது?","options":["யாமறிந்த மொழிகளிலே","வந்தே மாதரம்","தனிமை இரக்கம்","நெஞ்சு பொறுக்குதில்லையே"],"correctAnswer":2,"explanation":"மகாகவி பாரதியாரின் அச்சில் வெளிவந்த முதல் கவிதை 'தனிமை இரக்கம்' ஆகும். இப்பாடல் 1904-ஆம் ஆண்டு மதுரையிலிருந்து வெளியான 'விவேகபானு' என்ற இதழில் வெளியிடப்பட்டது.","difficulty":"hard","topic":"மகாகவி பாரதியார்"},{"id":820,"subject":"tamil","testNumber":9,"question":"பாரதியார் தமது ஞானகுருவாக ஏற்றுப் போற்றித் தம் 'சுதேச கீதங்கள்' நூலை யாருக்குச் சமர்ப்பணம் செய்தார்?","options":["பாலகங்காதர திலகர்","சகோதரி நிவேதிதா தேவி","அரவிந்தர்","சுவாமி விவேகானந்தர்"],"correctAnswer":1,"explanation":"சுவாமி விவேகானந்தரின் சீடரான சகோதரி நிவேதிதா தேவியை 1906-இல் கொல்கத்தாவில் சந்தித்த பாரதியார், அவரைத் தமது ஞானகுருவாக ஏற்றுக்கொண்டார். தமது 'சுதேச கீதங்கள்' மற்றும் 'ஜன்மபூமி' நூல்களை அவருக்குச் சமர்ப்பணம் செய்தார்.","difficulty":"hard","topic":"மகாகவி பாரதியார்"},{"id":821,"subject":"tamil","testNumber":9,"question":"பாவேந்தர் பாரதிதாசனின் இயற்பெயர் மற்றும் அவர் பிறந்த ஊர் எது?","options":["துரைராசு; பெரியகுளம்","இராசகோபாலன்; பழையனூர்","கனக சுப்புரத்தினம்; புதுச்சேரி","எத்திராசலு; வில்லியனூர்"],"correctAnswer":2,"explanation":"பாரதிதாசனின் இயற்பெயர் கனக சுப்புரத்தினம் ஆகும். இவர் 1891-ஆம் ஆண்டு ஏப்ரல் 29-ஆம் நாள் புதுச்சேரியில் கனகசபை – இலக்குமி அம்மாள் இணையருக்கு மகனாகப் பிறந்தார்.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":822,"subject":"tamil","testNumber":9,"question":"பாரதியாரின் முன்னிலையில் பாரதிதாசன் முதன்முதலாகப் பாடிப் பாரதியாரின் பாராட்டைப் பெற்ற பாடல் எது?","options":["புதியதோர் உலகம் செய்வோம்","தமிழுக்கும் அமுதென்று பேர்","வாழ்வினில் செம்மையைச் செய்பவள் நீயே","எங்கெங்கு காணினும் சக்தியடா"],"correctAnswer":3,"explanation":"திருமண விழா ஒன்றில் பாரதியார் முன்னிலையில் பாரதிதாசன் 'எங்கெங்கு காணினும் சக்தியடா' என்ற பாடலைப் பாடினார். அதனைக் கண்டு வியந்த பாரதியார், அப்பாடலை 'ஸ்ரீ சுப்பிரமணிய பாரதியாரின் கவிதா மண்டலத்தைச் சேர்ந்த கனக சுப்புரத்தினம் எழுதியது' எனக் குறிப்பிட்டு சுதேசமித்திரனுக்கு அனுப்பினார்.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":823,"subject":"tamil","testNumber":9,"question":"தமிழிலக்கிய உலகில் 'பாவேந்தர்' என்றும் 'புரட்சிக்கவிஞர்' என்றும் போற்றப்படுபவர் யார்?","options":["முடியரசன்","பாரதிதாசன்","கண்ணதாசன்","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":1,"explanation":"பெண் கல்வி, கைம்பெண் மறுமணம், பொதுவுடைமை, பகுத்தறிவு ஆகிய புரட்சிகரமான கருத்துகளைப் பாடியதால் பாரதிதாசன் 'புரட்சிக்கவிஞர்' எனவும், தமிழ்க்கவிதைக்குப் பெருமை சேர்த்ததால் 'பாவேந்தர்' எனவும் போற்றப்படுகிறார்.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":824,"subject":"tamil","testNumber":9,"question":"1969-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்ற பாரதிதாசனின் நாடக நூல் எது?","options":["சௌமியன்","பாண்டியன் பரிசு","சேர தாண்டவம்","பிசிராந்தையார்"],"correctAnswer":3,"explanation":"சங்க காலப் புலவர் பிசிராந்தையாருக்கும் கோப்பெருஞ்சோழனுக்கும் இடையிலான நட்பை மையமாகக் கொண்டு பாரதிதாசன் எழுதிய 'பிசிராந்தையார்' என்ற நாடக நூலுக்கு 1969-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":825,"subject":"tamil","testNumber":9,"question":"பாரதிதாசன் இயற்றிய 'குடும்ப விளக்கு' என்னும் நூல் எத்தனை பகுதிகளைக் கொண்டது?","options":["நான்கு பகுதிகள்","ஆறு பகுதிகள்","மூன்று பகுதிகள்","ஐந்து பகுதிகள்"],"correctAnswer":3,"explanation":"கல்விகற்ற பெண்ணால் ஒரு குடும்பம் எவ்வாறு விளக்கம் பெறும் என்பதைக் கூறும் 'குடும்ப விளக்கு' நூல் ஐந்து பகுதிகளைக் கொண்டது. அவை: ஒரு நாள் நிகழ்ச்சி, விருந்தோம்பல், திருமணம், மக்கட்பேறு, முதியோர் காதல் ஆகியனவாகும்.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":826,"subject":"tamil","testNumber":9,"question":"கல்வியறிவற்ற குடும்பத்தின் அவலநிலையைச் சித்தரிக்கும் பாரதிதாசனின் நூல் எது?","options":["குறிஞ்சித் திட்டு","இருண்ட வீடு","தமிழியக்கம்","அழகின் சிரிப்பு"],"correctAnswer":1,"explanation":"கற்ற பெண்ணால் சிறக்கும் குடும்பத்தைக் காட்டும் 'குடும்ப விளக்கு' நூலுக்கு எதிர்நிலையாக, கல்வியறிவும் ஒழுக்கமும் இல்லாத குடும்பம் அடையும் துன்பங்களை நகைச்சுவையுடனும் சீர்திருத்த நோக்குடனும் கூறும் பாரதிதாசனின் நூல் 'இருண்ட வீடு' ஆகும்.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":827,"subject":"tamil","testNumber":9,"question":"இயற்கையின் எழிலை அழகு, கடல், தென்றல், காடு, குன்றம், ஆறு முதலிய தலைப்புகளில் வருணிக்கும் பாரதிதாசனின் நூல் எது?","options":["கண்ணகி புரட்சிக் காப்பியம்","பாண்டியன் பரிசு","அழகின் சிரிப்பு","இசையமுது"],"correctAnswer":2,"explanation":"பாரதிதாசனின் இயற்கை வருணனைப் பாடல்களைக் கொண்ட சிறப்புமிக்க நூல் 'அழகின் சிரிப்பு' ஆகும். அழகு, கடல், தென்றல், காடு, குன்றம், ஆறு, தாமரை, ஞாயிறு, வான், கிளி, புறா, தமிழ் முதலிய தலைப்புகளில் அழகியல் மிளிரும் பாடல்கள் இதில் உள்ளன.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":828,"subject":"tamil","testNumber":9,"question":"கதிர்நாட்டு அரசன், அன்னம், வேலன், நரிக்கண்ணன் ஆகிய கதைமாந்தர்கள் இடம்பெறும் பாரதிதாசனின் குறுங்காவியம் எது?","options":["சஞ்சீவி பர்வதத்தின் சாரல்","பாண்டியன் பரிசு","புரட்சிக்கவி","எதிர்பாராத முத்தம்"],"correctAnswer":1,"explanation":"'பாண்டியன் பரிசு' என்பது பாரதிதாசன் இயற்றிய புகழ்பெற்ற குறுங்காவியமாகும். இதில் கதிர்நாட்டு அரசன், இளவரசி அன்னம், வீரன் வேலன், சதிகாரன் நரிக்கண்ணன் ஆகிய பாத்திரங்கள் மூலம் மக்களாட்சியின் மாண்பு உணர்த்தப்படுகிறது.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":829,"subject":"tamil","testNumber":9,"question":"தமிழ்மொழியின் வளர்ச்சிக்காக வணிகர், ஆசிரியர், மாணவர், அரசியலார் முதலியோருக்கு அறிவுறுத்தி ஒரே இரவில் பாரதிதாசன் எழுதியதாகக் கருதப்படும் நூல் எது?","options":["தமிழியக்கம்","தமிழச்சியின் கத்தி","மணிமேகலை வெண்பா","இசையமுது"],"correctAnswer":0,"explanation":"தமிழ் எங்கும் தழைக்க வேண்டும் என்ற உணர்வோடு, சமுதாயத்தின் பல்வேறு பிரிவினரும் ஆற்ற வேண்டிய தமிழ்த்தொண்டை வலியுறுத்திப் பாரதிதாசன் ஒரே இரவில் இயற்றியதாகக் கூறப்படும் நூல் 'தமிழியக்கம்' ஆகும்.","difficulty":"hard","topic":"பாரதிதாசன்"},{"id":830,"subject":"tamil","testNumber":9,"question":"வடமொழியில் உள்ள 'பில்ஹணீயம்' என்னும் நூலைத் தழுவிப் பாரதிதாசன் இயற்றிய குறுங்காவியம் எது?","options":["எதிர்பாராத முத்தம்","குறிஞ்சித் திட்டு","காதலா? கடமையா?","புரட்சிக்கவி"],"correctAnswer":3,"explanation":"வடமொழியின் 'பில்ஹணீயம்' என்ற காப்பியத்தைத் தழுவி, முடியாட்சியை எதிர்த்து மக்களாட்சியையும் காதலின் மாண்பையும் போற்றும் வகையில் உதாரன் – அமுதவல்லி கதையாகப் பாரதிதாசன் இயற்றிய நூல் 'புரட்சிக்கவி' ஆகும்.","difficulty":"hard","topic":"பாரதிதாசன்"},{"id":831,"subject":"tamil","testNumber":9,"question":"பாவேந்தர் பாரதிதாசன் புதுச்சேரியில் நடத்திய இலக்கிய இதழின் பெயர் என்ன?","options":["காவியம்","தென்றல்","குயில்","எழுத்து"],"correctAnswer":2,"explanation":"பாரதிதாசன் 'குயில்' என்னும் இலக்கிய இதழை நடத்தினார். இவ்விதழின் வழியாகத் தமிழ் உணர்வு, சமூகச் சீர்திருத்தம் மற்றும் இளங்கவிஞர்களின் படைப்புகளை ஊக்குவித்தார்.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":832,"subject":"tamil","testNumber":9,"question":"புதுச்சேரி அரசின் தமிழ்த்தாய் வாழ்த்துப் பாடலாகப் போற்றப்படும் பாரதிதாசனின் பாடல் எது?","options":["வாழ்வினில் செம்மையைச் செய்பவள் நீயே","தமிழுக்கும் அமுதென்று பேர்","நீராருங் கடலுடுத்த நிலமடந்தை","எங்கள் வாழ்வும் எங்கள் வளமும்"],"correctAnswer":0,"explanation":"பாரதிதாசன் இயற்றிய 'வாழ்வினில் செம்மையைச் செய்பவள் நீயே; மாண்புகள் நீயே என் தமிழ்த்தாயே' என்ற பாடலைப் புதுச்சேரி அரசு தனது தமிழ்த்தாய் வாழ்த்துப் பாடலாக ஏற்றுக்கொண்டுள்ளது.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":833,"subject":"tamil","testNumber":9,"question":"\"தமிழுக்கும் அமுதென்று பேர் – அந்தத் தமிழ் இன்பத் தமிழ் எங்கள் உயிருக்கு நேர்\" என்ற புகழ்பெற்ற பாடலை இயற்றியவர் யார்?","options":["பாரதியார்","வாணிதாசன்","பாரதிதாசன்","நாமக்கல் கவிஞர்"],"correctAnswer":2,"explanation":"தமிழ்மொழியை அமுது, நிலவு, மணம், பால், வேல், வான், தோள், வாள் எனப் பலவாறு போற்றும் 'இன்பத்தமிழ்' ('தமிழுக்கும் அமுதென்று பேர்') என்ற புகழ்பெற்ற பாடலைப் பாவேந்தர் பாரதிதாசன் இயற்றியுள்ளார்.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":834,"subject":"tamil","testNumber":9,"question":"\"எங்கள் வாழ்வும் எங்கள் வளமும் மங்காத தமிழென்று சங்கே முழங்கு\" என்று முழங்கிய கவிஞர் யார்?","options":["பாரதிதாசன்","சுரதா","முடியரசன்","கவிமணி"],"correctAnswer":0,"explanation":"தமிழர்களின் வாழ்வும் வளமும் நிலைத்த புகழுடைய தமிழ்மொழியே எனப் பெருமிதத்துடன் 'எங்கள் வாழ்வும் எங்கள் வளமும் மங்காத தமிழென்று சங்கே முழங்கு' என்று பாடியவர் பாரதிதாசன் ஆவார்.","difficulty":"easy","topic":"பாரதிதாசன்"},{"id":835,"subject":"tamil","testNumber":9,"question":"\"கல்வியில்லாத பெண்கள் களர்நிலம்; அந்நிலத்தில் புல்விளைந்திடலாம் நல்ல புதல்வர்கள் விளைதல் இல்லை\" என்ற வரிகள் பாரதிதாசனின் எந்த நூலில் இடம்பெற்றுள்ளன?","options":["தமிழியக்கம்","குடும்ப விளக்கு","பாண்டியன் பரிசு","இருண்ட வீடு"],"correctAnswer":1,"explanation":"பெண் கல்வியின் இன்றியமையாமையை வலியுறுத்தும் 'கல்வியில்லாத பெண்கள் களர்நிலம்' என்ற புகழ்பெற்ற வரிகள் பாரதிதாசன் இயற்றிய 'குடும்ப விளக்கு' என்னும் நூலில் இடம்பெற்றுள்ளன.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":836,"subject":"tamil","testNumber":9,"question":"\"புதியதோர் உலகம் செய்வோம் – கெட்ட போரிடும் உலகத்தை வேரோடு சாய்ப்போம்\" என்று பாடிய கவிஞர் யார்?","options":["பட்டுக்கோட்டை கல்யாணசுந்தரம்","பாரதிதாசன்","நாமக்கல் கவிஞர்","மகாகவி பாரதியார்"],"correctAnswer":1,"explanation":"உலக அமைதி, சமத்துவம் மற்றும் பொதுவுடைமைச் சமுதாயத்தைக் காண விரும்பிய பாரதிதாசன் 'புதியதோர் உலகம் செய்வோம் – கெட்ட போரிடும் உலகத்தை வேரோடு சாய்ப்போம்' என்று முழங்கினார்.","difficulty":"medium","topic":"பாரதிதாசன்"},{"id":837,"subject":"tamil","testNumber":9,"question":"\"இருட்டறையில் உள்ளதடா உலகம்; சாதி இருக்கின்ற தென்பானும் இருக்கின்றானே\" என்ற சமூகச் சீர்திருத்த வரிகளைப் பாடியவர் யார்?","options":["கண்ணதாசன்","உடுமலை நாராயணகவி","பாரதிதாசன்","தமிழ்ஒளி"],"correctAnswer":2,"explanation":"சாதி வேறுபாடுகளைக் கடுமையாகச் சாடி, சமத்துவச் சமுதாயத்தை உருவாக்க வேண்டும் என்ற நோக்கில் 'இருட்டறையில் உள்ளதடா உலகம்; சாதி இருக்கின்ற தென்பானும் இருக்கின்றானே' எனப் பாரதிதாசன் பாடியுள்ளார்.","difficulty":"hard","topic":"பாரதிதாசன்"},{"id":838,"subject":"tamil","testNumber":9,"question":"பின்வரும் நூல்களுள் பாரதிதாசன் இயற்றாத நூல் எது?","options":["குறிஞ்சித் திட்டு","எதிர்பாராத முத்தம்","சஞ்சீவி பர்வதத்தின் சாரல்","கொடிமுல்லை"],"correctAnswer":3,"explanation":"சஞ்சீவி பர்வதத்தின் சாரல், எதிர்பாராத முத்தம், குறிஞ்சித் திட்டு ஆகிய மூன்றும் பாரதிதாசன் இயற்றிய நூல்களாகும். 'கொடிமுல்லை' என்பது பாரதிதாசனின் மாணவரான வாணிதாசன் இயற்றிய நூலாகும்.","difficulty":"hard","topic":"பாரதிதாசன்"},{"id":839,"subject":"tamil","testNumber":9,"question":"காந்தியடிகளின் கொள்கைகளால் ஈர்க்கப்பட்டுப் பாடல்கள் இயற்றியதால் 'காந்தியக் கவிஞர்' என அழைக்கப்படுபவர் யார்?","options":["மகாகவி பாரதியார்","கவிமணி தேசிக விநாயகம் பிள்ளை","நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்","அழ.வள்ளியப்பா"],"correctAnswer":2,"explanation":"நாமக்கல் மாவட்டத்தில் உள்ள மோகனூரில் பிறந்த வெ.இராமலிங்கனார், காந்தியடிகளின் அகிம்சை மற்றும் விடுதலைக் கொள்கைகளைத் தமது பாடல்களில் பரப்பியதால் 'காந்தியக் கவிஞர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":840,"subject":"tamil","testNumber":9,"question":"தமிழகத்தின் முதல் அரசவைக் கவிஞராக 1949-ஆம் ஆண்டு நியமிக்கப்பட்டவர் யார்?","options":["பாரதிதாசன்","கவிமணி தேசிக விநாயகம் பிள்ளை","நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்","கண்ணதாசன்"],"correctAnswer":2,"explanation":"தமிழறிஞர், கவிஞர், விடுதலைப் போராட்ட வீரர் மற்றும் சிறந்த ஓவியராக விளங்கிய நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் 1949-ஆம் ஆண்டு தமிழகத்தின் முதல் அரசவைக் கவிஞராக நியமிக்கப்பட்டார். இந்திய அரசு இவருக்கு 'பத்மபூஷண்' விருது வழங்கியுள்ளது.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":841,"subject":"tamil","testNumber":9,"question":"1930-ஆம் ஆண்டு வேதாரண்யம் உப்புச் சத்தியாக்கிரகப் போராட்டத்தின்போது நாமக்கல் கவிஞர் இயற்றிய வழிநடைப் பாடல் எது?","options":["வீர சுதந்திரம் வேண்டி நின்றார்","வந்தே மாதரம் என்போம்","ஆடுவோமே பள்ளுப் பாடுவோமே","கத்தியின்றி ரத்தமின்றி யுத்தமொன்று வருகுது"],"correctAnswer":3,"explanation":"இராஜாஜி தலைமையில் 1930-ஆம் ஆண்டு நடைபெற்ற வேதாரண்யம் உப்புச் சத்தியாக்கிரகப் பாதயாத்திரையின்போது தொண்டர்களுக்கு எழுச்சியூட்டும் விதமாக 'கத்தியின்றி ரத்தமின்றி யுத்தமொன்று வருகுது' என்ற பாடலை நாமக்கல் கவிஞர் இயற்றினார்.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":842,"subject":"tamil","testNumber":9,"question":"நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் எழுதிய தன்வரலாற்று நூலின் பெயர் என்ன?","options":["என் கதை","என் சரித்திரம்","வனவாசம்","வாழ்க்கைக் குறிப்புகள்"],"correctAnswer":0,"explanation":"'என் கதை' என்பது நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் எழுதிய தன்வரலாற்று நூலாகும். ('என் சரித்திரம்' – உ.வே.சாமிநாதையர்; 'வனவாசம்' – கண்ணதாசன்; 'வாழ்க்கைக் குறிப்புகள்' – திரு.வி.க.)","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":843,"subject":"tamil","testNumber":9,"question":"நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் எழுதிய புகழ்பெற்ற புதினம் எது?","options":["வாடிவாசல்","கள்ளிக்காட்டு இதிகாசம்","சேரமான் காதலி","மலைக்கள்ளன்"],"correctAnswer":3,"explanation":"'மலைக்கள்ளன்' என்பது நாமக்கல் கவிஞர் எழுதிய புகழ்பெற்ற சமூகப் புதினமாகும். இந்நூல் பின்னர் திரைப்படமாக எடுக்கப்பட்டுப் பெரும் வரவேற்பைப் பெற்றது.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":844,"subject":"tamil","testNumber":9,"question":"'தமிழன் இதயம்', 'சங்கொலி', 'அவனும் அவளும்' ஆகிய நூல்களை இயற்றியவர் யார்?","options":["முடியரசன்","கவிமணி தேசிக விநாயகம் பிள்ளை","நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்","சுரதா"],"correctAnswer":2,"explanation":"தமிழன் இதயம், சங்கொலி (கவிதைத் தொகுப்புகள்), அவனும் அவளும் (காவியம்), மலைக்கள்ளன் (புதினம்), என் கதை (தன்வரலாறு), காந்தி அஞ்சலி ஆகியவை நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் இயற்றிய நூல்களாகும்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":845,"subject":"tamil","testNumber":9,"question":"\"தமிழன் என்றோர் இனமுண்டு; தனியே அவர்க்கொரு குணமுண்டு; அமிழ்தம் அவனுடை மொழியாகும்; அன்பே அவனுடை வழியாகும்\" எனப் பாடியவர் யார்?","options":["பாரதிதாசன்","வாணிதாசன்","மகாகவி பாரதியார்","நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்"],"correctAnswer":3,"explanation":"தமிழரின் தனித்தன்மையையும் அன்பு நெறியையும் போற்றும் 'தமிழன் என்றோர் இனமுண்டு; தனியே அவர்க்கொரு குணமுண்டு' என்ற புகழ்பெற்ற வரிகளை இயற்றியவர் நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் ஆவார்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":846,"subject":"tamil","testNumber":9,"question":"\"அருள்நெறி அறிவைத் தரலாகும்; அதுவே தமிழன் குரலாகும்\" மற்றும் \"கைத்தொழில் ஒன்றைக் கற்றுக்கொள்; கவலை உனக்கில்லை ஒத்துக்கொள்\" என்ற வரிகளின் ஆசிரியர் யார்?","options":["நாமக்கல் கவிஞர் வெ.இராமலிங்கனார்","கவிமணி தேசிக விநாயகம் பிள்ளை","உடுமலை நாராயணகவி","பட்டுக்கோட்டை கல்யாணசுந்தரம்"],"correctAnswer":0,"explanation":"'அருள்நெறி அறிவைத் தரலாகும்' என்ற 'எங்கள் தமிழ்' பாடலையும், உழைப்பின் சிறப்பை உணர்த்தும் 'கைத்தொழில் ஒன்றைக் கற்றுக்கொள்; கவலை உனக்கில்லை ஒத்துக்கொள்' என்ற வரிகளையும் இயற்றியவர் நாமக்கல் கவிஞர் வெ.இராமலிங்கனார் ஆவார்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":847,"subject":"tamil","testNumber":9,"question":"கன்னியாகுமரி மாவட்டம் தேரூரில் பிறந்த தேசிக விநாயகம் பிள்ளைக்கு 'கவிமணி' என்னும் பட்டத்தை 1940-ஆம் ஆண்டு வழங்கியவர் யார்?","options":["உ.வே.சாமிநாதையர்","தமிழவேள் உமாமகேசுவரனார்","திரு.வி.கலியாணசுந்தரனார்","மறைமலையடிகள்"],"correctAnswer":1,"explanation":"கன்னியாகுமரி மாவட்டம் தேரூரில் பிறந்து 36 ஆண்டுகள் ஆசிரியராகப் பணியாற்றிய தேசிக விநாயகம் பிள்ளைக்கு 1940-ஆம் ஆண்டு சென்னை மாகாணத் தமிழ்ச் சங்கத்தின் சார்பில் தமிழவேள் உமாமகேசுவரனார் 'கவிமணி' என்ற பட்டத்தை வழங்கிச் சிறப்பித்தார்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":848,"subject":"tamil","testNumber":9,"question":"கவிமணி தேசிக விநாயகம் பிள்ளை இயற்றிய 'ஆசிய ஜோதி' என்ற நூல் எந்த ஆங்கில நூலைத் தழுவி எழுதப்பட்டது?","options":["லார்டு டென்னிசன் எழுதிய 'இன் மெமோரியம்'","வில்லியம் வேர்ட்ஸ்வொர்த் எழுதிய 'பிரிளூட்'","எட்வர்ட் பிட்ஸ்ஜெரால்டு எழுதிய 'ருபாயத்'","எட்வின் அர்னால்டு எழுதிய 'தி லைட் ஆஃப் ஏசியா'"],"correctAnswer":3,"explanation":"எட்வின் அர்னால்டு ஆங்கிலத்தில் எழுதிய 'The Light of Asia' என்ற நூலைத் தழுவிப் புத்தரின் வாழ்க்கை வரலாற்றையும் கருணை உள்ளத்தையும் கூறும் வகையில் கவிமணி இயற்றிய நூல் 'ஆசிய ஜோதி' ஆகும்.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":849,"subject":"tamil","testNumber":9,"question":"நாஞ்சில் நாட்டில் நிலவிய மருமக்கள் தாய முறையில் இருந்த குறைகளை நகைச்சுவையுடன் சாடி கவிமணி இயற்றிய அங்கத நூல் எது?","options":["மருமக்கள் வழி மான்மியம்","கதர் பிறந்த கதை","தேவியின் கீர்த்தனங்கள்","மலரும் மாலையும்"],"correctAnswer":0,"explanation":"நாஞ்சில் நாட்டில் வழக்கிலிருந்த மருமக்கள் தாய முறையினால் குடும்பங்களில் ஏற்பட்ட அவலங்களை நகைச்சுவையும் அங்கதமும் மிளிரக் கவிமணி தேசிக விநாயகம் பிள்ளை இயற்றிய நூல் 'மருமக்கள் வழி மான்மியம்' ஆகும்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":850,"subject":"tamil","testNumber":9,"question":"பாரசீகக் கவிஞர் உமர்கய்யாமின் 'ருபாயத்' பாடல்களை எட்வர்ட் பிட்ஸ்ஜெரால்டின் ஆங்கில மொழிபெயர்ப்பிலிருந்து தமிழில் 'உமர்கய்யாம் பாடல்கள்' என மொழிபெயர்த்தவர் யார்?","options":["கண்ணதாசன்","கவிமணி தேசிக விநாயகம் பிள்ளை","நாமக்கல் கவிஞர்","மகாகவி பாரதியார்"],"correctAnswer":1,"explanation":"பாரசீகக் கவிஞர் உமர்கய்யாமின் 'ருபாயத்' என்ற நான்கடிப் பாடல்களை ஆங்கிலத்தில் எட்வர்ட் பிட்ஸ்ஜெரால்டு மொழிபெயர்த்தார். அதனைத் தழுவி இனிய தமிழில் 'உமர்கய்யாம் பாடல்கள்' என்ற பெயரில் கவிமணி தேசிக விநாயகம் பிள்ளை படைத்தார்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":851,"subject":"tamil","testNumber":9,"question":"'மலரும் மாலையும்', 'தேவியின் கீர்த்தனங்கள்', 'குழந்தைச் செல்வம்' ஆகிய கவிதை நூல்களை இயற்றியவர் யார்?","options":["அழ.வள்ளியப்பா","நாமக்கல் கவிஞர்","கவிமணி தேசிக விநாயகம் பிள்ளை","சுரதா"],"correctAnswer":2,"explanation":"மலரும் மாலையும், ஆசிய ஜோதி, மருமக்கள் வழி மான்மியம், உமர்கய்யாம் பாடல்கள், தேவியின் கீர்த்தனங்கள், குழந்தைச் செல்வம், கதர் பிறந்த கதை ஆகியன கவிமணி தேசிக விநாயகம் பிள்ளையின் புகழ்பெற்ற நூல்களாகும்.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":852,"subject":"tamil","testNumber":9,"question":"\"மங்கையராய்ப் பிறப்பதற்கே நல்ல மாதவம் செய்திட வேண்டுமம்மா\" என்று பெண்களின் பெருமையைப் பாடிய கவிஞர் யார்?","options":["கவிமணி தேசிக விநாயகம் பிள்ளை","மகாகவி பாரதியார்","வாணிதாசன்","பாரதிதாசன்"],"correctAnswer":0,"explanation":"பெண்களின் பெருமையையும் தாய்மையின் சிறப்பையும் போற்றி 'மங்கையராய்ப் பிறப்பதற்கே நல்ல மாதவம் செய்திட வேண்டுமம்மா' என்று பாடியவர் கவிமணி தேசிக விநாயகம் பிள்ளை ஆவார்.","difficulty":"easy","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":853,"subject":"tamil","testNumber":9,"question":"\"உள்ளத்து உள்ளது கவிதை – இன்பம் உருவெடுப்பது கவிதை; தெள்ளத் தெளிந்த தமிழில் உண்மை தெரிந்துரைப்பது கவிதை\" என்ற வரிகளை இயற்றியவர் யார்?","options":["முடியரசன்","கவிமணி தேசிக விநாயகம் பிள்ளை","கண்ணதாசன்","சுரதா"],"correctAnswer":1,"explanation":"கவிதையின் இலக்கணத்தை எளிமையும் இனிமையும் பொருந்த 'உள்ளத்து உள்ளது கவிதை – இன்பம் உருவெடுப்பது கவிதை' என வரையறுத்துப் பாடியவர் கவிமணி தேசிக விநாயகம் பிள்ளை ஆவார்.","difficulty":"medium","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":854,"subject":"tamil","testNumber":9,"question":"கவிமணி தேசிக விநாயகம் பிள்ளை எழுதிய வரலாற்று ஆராய்ச்சி நூல் எது?","options":["குறிஞ்சித் திட்டு","காந்தளூர்ச் சாலை","கல்வெட்டுக் கலை","தமிழர் வரலாறு"],"correctAnswer":1,"explanation":"கவிஞராக மட்டுமல்லாமல் சிறந்த கல்வெட்டு மற்றும் வரலாற்று ஆய்வாளராகவும் திகழ்ந்த கவிமணி தேசிக விநாயகம் பிள்ளை 'காந்தளூர்ச் சாலை' என்னும் சிறந்த வரலாற்று ஆராய்ச்சி நூலை எழுதியுள்ளார்.","difficulty":"hard","topic":"நாமக்கல் கவிஞர் & கவிமணி"},{"id":855,"subject":"tamil","testNumber":9,"question":"'கவியரசு' எனப் போற்றப்படும் கண்ணதாசனின் இயற்பெயர் மற்றும் அவர் பிறந்த ஊர் எது?","options":["இராசகோபாலன்; பழையனூர்","விஜயரங்கம்; ஆடூர்","துரைராசு; பெரியகுளம்","முத்தையா; சிறுகூடல்பட்டி"],"correctAnswer":3,"explanation":"'கவியரசு' கண்ணதாசனின் இயற்பெயர் முத்தையா ஆகும். இவர் சிவகங்கை மாவட்டத்தில் உள்ள சிறுகூடல்பட்டியில் பிறந்தார். தமிழக அரசின் அரசவைக் கவிஞராகவும் பணியாற்றினார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":856,"subject":"tamil","testNumber":9,"question":"கண்ணதாசனுக்கு 1980-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றுத் தந்த வரலாற்றுப் புதினம் எது?","options":["சேரமான் காதலி","ஆட்டனத்தி ஆதிமந்தி","மாங்கனி","இயேசு காவியம்"],"correctAnswer":0,"explanation":"கண்ணதாசன் எழுதிய 'சேரமான் காதலி' என்னும் வரலாற்றுப் புதினத்திற்கு 1980-ஆம் ஆண்டு இந்திய அரசின் உயரிய இலக்கிய விருதான சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":857,"subject":"tamil","testNumber":9,"question":"கண்ணதாசன் இறுதியாக இயற்றிய காவியம் மற்றும் அவரது தன்வரலாற்று நூல் ஆகியவற்றின் சரியான இணை எது?","options":["இயேசு காவியம் – வனவாசம்","ஆட்டனத்தி ஆதிமந்தி – மனவாசம்","மாங்கனி – என் கதை","கள்ளக்குடி மாகாவியம் – என் சரித்திரம்"],"correctAnswer":0,"explanation":"கவியரசு கண்ணதாசன் தமது இறுதிக்காலத்தில் இயற்றிய புகழ்பெற்ற காவியம் 'இயேசு காவியம்' ஆகும். அவரது அரசியல் மற்றும் இளமைக்கால வாழ்வைக் கூறும் தன்வரலாற்று நூல் 'வனவாசம்' ஆகும்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":858,"subject":"tamil","testNumber":9,"question":"இயற்கை வருணனைப் பாடல்களுக்காகத் 'தமிழகத்தின் வேர்ட்ஸ்வொர்த்' எனப் போற்றப்படும் வாணிதாசனின் இயற்பெயர் என்ன?","options":["அரங்கநாதன்","ந.ஜெகதீசன்","ச.கல்யாணசுந்தரம்","அரங்கசாமி என்கிற எத்திராசலு"],"correctAnswer":3,"explanation":"புதுச்சேரி வில்லியனூரில் பிறந்த வாணிதாசனின் இயற்பெயர் அரங்கசாமி என்கிற எத்திராசலு ஆகும். பாரதிதாசனின் மாணவரான இவர் 'தமிழகத்தின் வேர்ட்ஸ்வொர்த்', 'கவிஞரேறு', 'பாவலர்மணி' ஆகிய சிறப்புப் பெயர்களால் போற்றப்படுகிறார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":859,"subject":"tamil","testNumber":9,"question":"பிரெஞ்சு அரசின் உயரிய விருதான 'செவாலியர்' விருது பெற்ற மரபுக் கவிஞர் யார்?","options":["முடியரசன்","வாணிதாசன்","சுரதா","தமிழ்ஒளி"],"correctAnswer":1,"explanation":"தமிழ், தெலுங்கு, ஆங்கிலம், பிரெஞ்சு ஆகிய மொழிகளில் புலமை பெற்ற கவிஞர் வாணிதாசனுக்குப் பிரெஞ்சு அரசு 'செவாலியர்' விருது வழங்கிச் சிறப்பித்தது.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":860,"subject":"tamil","testNumber":9,"question":"'தமிழச்சி', 'கொடிமுல்லை', 'தொடுவானம்', 'எழிலோவியம்' ஆகிய கவிதை நூல்களை இயற்றியவர் யார்?","options":["பாரதிதாசன்","முடியரசன்","சுரதா","வாணிதாசன்"],"correctAnswer":3,"explanation":"தமிழச்சி, கொடிமுல்லை, தொடுவானம், எழிலோவியம், குழந்தை இலக்கியம், இரவு வரவில்லை ஆகியன வாணிதாசன் இயற்றிய புகழ்பெற்ற நூல்களாகும். 'ஓடையாட உள்ளம் தூண்டுதே' என்ற புகழ்பெற்ற பாடல் இவரது 'தொடுவானம்' நூலில் இடம்பெற்றுள்ளது.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":861,"subject":"tamil","testNumber":9,"question":"பாரதிதாசன் மீது கொண்ட பற்றினால் 'சுப்புரத்தினதாசன்' என்பதன் சுருக்கமாகத் தம் பெயரை 'சுரதா' என மாற்றிக்கொண்ட இவரின் இயற்பெயர் மற்றும் சிறப்புப் பெயர் யாது?","options":["துரைராசு; திராவிட நாட்டின் வானம்பாடி","முத்தையா; கவியரசு","இராசகோபாலன்; உவமைக் கவிஞர்","விஜயரங்கம்; மக்கள் கவிஞர்"],"correctAnswer":2,"explanation":"தஞ்சாவூர் மாவட்டம் பழையனூரில் பிறந்த இராசகோபாலன், பாரதிதாசனின் இயற்பெயரான சுப்புரத்தினத்தின் மீது கொண்ட பற்றால் 'சுரதா' எனத் தம் பெயரை மாற்றிக்கொண்டார். தம் கவிதைகளில் புதுமையான உவமைகளைப் படைத்ததால் 'உவமைக் கவிஞர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":862,"subject":"tamil","testNumber":9,"question":"தமிழக அரசின் பரிசு பெற்ற 'தேன்மழை' மற்றும் 'துறைமுகம்', 'சுவரும் சுண்ணாம்பும்' ஆகிய நூல்களின் ஆசிரியர் யார்?","options":["கண்ணதாசன்","வாணிதாசன்","முடியரசன்","சுரதா"],"correctAnswer":3,"explanation":"உவமைக் கவிஞர் சுரதா இயற்றிய 'தேன்மழை' கவிதைத் தொகுப்பு தமிழக அரசின் பரிசைப் பெற்றது. துறைமுகம், சுவரும் சுண்ணாம்பும், அமுதும் தேனும், சாவின் முத்தம் ஆகியன இவரது பிற புகழ்பெற்ற நூல்களாகும்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":863,"subject":"tamil","testNumber":9,"question":"முழுக்க முழுக்கக் கவிதைகளை மட்டுமே கொண்ட 'காவியம்' என்னும் இலக்கிய இதழை நடத்திய கவிஞர் யார்?","options":["சி.சு.செல்லப்பா","மீரா","பாரதிதாசன்","சுரதா"],"correctAnswer":3,"explanation":"உவமைக் கவிஞர் சுரதா முழுக்க முழுக்கக் கவிதைகளால் மட்டுமே ஆன 'காவியம்' என்ற இதழை நடத்தினார். மேலும் இலக்கியம், விண்மீன், ஊர்வலம் ஆகிய இலக்கிய இதழ்களையும் நடத்தியுள்ளார்.","difficulty":"hard","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":864,"subject":"tamil","testNumber":9,"question":"'திராவிட நாட்டின் வானம்பாடி' என அறிஞர் அண்ணாவால் பாராட்டப்பட்ட கவிஞர் முடியரசனின் இயற்பெயர் என்ன?","options":["எத்திராசலு","இராசகோபாலன்","இராதாகிருஷ்ணன்","துரைராசு"],"correctAnswer":3,"explanation":"தேனி மாவட்டம் பெரியகுளத்தில் பிறந்த முடியரசனின் இயற்பெயர் துரைராசு ஆகும். இவர் அறிஞர் அண்ணாவால் 'திராவிட நாட்டின் வானம்பாடி' எனவும், குன்றக்குடி அடிகளாரால் 'கவியரசு' எனவும் பாராட்டப்பட்டார்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":865,"subject":"tamil","testNumber":9,"question":"'பூங்கொடி', 'வீரகாவியம்', 'காவியப் பாவை' ஆகிய நூல்களை இயற்றிய கவிஞர் யார்?","options":["முடியரசன்","சுரதா","வாணிதாசன்","தமிழ்ஒளி"],"correctAnswer":0,"explanation":"பூங்கொடி (தமிழக அரசின் பரிசு பெற்ற காவியம்), வீரகாவியம், காவியப் பாவை, முடியரசன் கவிதைகள் ஆகியன கவிஞர் முடியரசன் இயற்றிய புகழ்பெற்ற நூல்களாகும்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":866,"subject":"tamil","testNumber":9,"question":"\"கல்லெடுத்து முள்ளெடுத்துக் காட்டுப் பெருவெளியை மல்லெடுத்த திண்டோள் மரத்தால் வளப்படுத்தி\" என்ற 'நானிலம் படைத்தவன்' பாடலை இயற்றியவர் யார்?","options":["கண்ணதாசன்","பாரதிதாசன்","முடியரசன்","பட்டுக்கோட்டை கல்யாணசுந்தரம்"],"correctAnswer":2,"explanation":"தமிழர்களின் வீரத்தையும் நிலம் திருத்தி நாகரிகம் படைத்த சிறப்பையும் போற்றும் 'நானிலம் படைத்தவன்' என்ற பாடலை முடியரசன் இயற்றியுள்ளார். இது அவரது 'புதியதொரு விதி செய்வோம்' என்ற நூலில் இடம்பெற்றுள்ளது.","difficulty":"hard","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":867,"subject":"tamil","testNumber":9,"question":"நாட்டுப்புற இசையின் எளிமையைக் கையாண்டு திரையிசைப் பாடல்களில் பகுத்தறிவுக் கருத்துகளைப் பரப்பியதால் 'பகுத்தறிவுக் கவிராயர்' எனப் போற்றப்படுபவர் யார்?","options":["கண்ணதாசன்","உடுமலை நாராயணகவி","பட்டுக்கோட்டை கல்யாணசுந்தரம்","மருதகாசி"],"correctAnswer":1,"explanation":"திருப்பூர் மாவட்டம் உடுமலைப்பேட்டை அருகே பூளவாடியில் பிறந்த உடுமலை நாராயணகவி, தமது திரையிசைப் பாடல்கள் மூலம் சாதி மறுப்பு, மூடநம்பிக்கை ஒழிப்பு மற்றும் பகுத்தறிவுக் கருத்துகளைப் பரப்பியதால் 'பகுத்தறிவுக் கவிராயர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":868,"subject":"tamil","testNumber":9,"question":"\"ஒன்றல்ல இரண்டல்ல தம்பி – சொல்ல ஒப்புமை இல்லாத அற்புதம் தமிழ்நாட்டில்\" என்ற பாடலை இயற்றியவர் யார்?","options":["நாமக்கல் கவிஞர்","பட்டுக்கோட்டை கல்யாணசுந்தரம்","மருதகாசி","உடுமலை நாராயணகவி"],"correctAnswer":3,"explanation":"தமிழ்நாட்டின் இயற்கை வளம், இலக்கியச் சிறப்பு மற்றும் கொடை வள்ளல்களின் பெருமையை எளிய தமிழில் பாடும் 'ஒன்றல்ல இரண்டல்ல தம்பி' என்ற பாடலைப் பகுத்தறிவுக் கவிராயர் உடுமலை நாராயணகவி இயற்றியுள்ளார்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":869,"subject":"tamil","testNumber":9,"question":"உழைப்பாளர்களின் உயர்வையும் சமூகச் சீர்திருத்தக் கருத்துகளையும் எளிய தமிழில் திரையிசைப் பாடல்களாகப் படைத்ததால் 'மக்கள் கவிஞர்' என அழைக்கப்படுபவர் யார்?","options":["கண்ணதாசன்","பட்டுக்கோட்டை கல்யாணசுந்தரம்","மருதகாசி","உடுமலை நாராயணகவி"],"correctAnswer":1,"explanation":"தஞ்சாவூர் மாவட்டம் செங்கப்படுத்தான்காட்டில் பிறந்த பட்டுக்கோட்டை கல்யாணசுந்தரம், பொதுவுடைமைச் சிந்தனைகளையும் உழைக்கும் மக்களின் வாழ்வியலையும் எளிய இனிய திரையிசைப் பாடல்களாகப் படைத்ததால் 'மக்கள் கவிஞர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":870,"subject":"tamil","testNumber":9,"question":"\"ஏட்டில் படித்ததோடு இருந்துவிடாதே – நீ ஏன் படித்தோம் என்பதையும் மறந்துவிடாதே\" என்ற அறிவுரைப் பாடலை இயற்றியவர் யார்?","options":["பட்டுக்கோட்டை கல்யாணசுந்தரம்","உடுமலை நாராயணகவி","அழ.வள்ளியப்பா","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":0,"explanation":"கல்வி கற்பதன் உண்மையான நோக்கத்தையும் நன்னெறி ஒழுக்கத்தையும் வலியுறுத்தும் 'ஏட்டில் படித்ததோடு இருந்துவிடாதே' ('துன்பம் வெல்லும் கல்வி') என்ற புகழ்பெற்ற பாடலை மக்கள் கவிஞர் பட்டுக்கோட்டை கல்யாணசுந்தரம் இயற்றியுள்ளார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":871,"subject":"tamil","testNumber":9,"question":"'திரைக்கவித் திலகம்' என்ற சிறப்புப் பட்டத்தைப் பெற்ற திரையிசைக் கவிஞர் யார்?","options":["வாலி","உடுமலை நாராயணகவி","அ.மருதகாசி","பட்டுக்கோட்டை கல்யாணசுந்தரம்"],"correctAnswer":2,"explanation":"திருச்சிராப்பள்ளி மாவட்டம் மேலக்குடிகாட்டில் பிறந்த அ.மருதகாசி, தமிழ்த் திரையுலகில் 4,000-க்கும் மேற்பட்ட பொருட்செறிவுமிக்க பாடல்களை எழுதியதற்காக 'திரைக்கவித் திலகம்' என்ற பட்டத்தைப் பெற்றார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":872,"subject":"tamil","testNumber":9,"question":"\"ஏர்முனைக்கு நேர் இங்கே எதுவுமே இல்லை – என்றும் நம் வாழ்விலே பஞ்சமே இல்லை\" என்ற உழவுப் பெருமைப் பாடலை இயற்றியவர் யார்?","options":["கண்ணதாசன்","உடுமலை நாராயணகவி","பட்டுக்கோட்டை கல்யாணசுந்தரம்","அ.மருதகாசி"],"correctAnswer":3,"explanation":"உழவர்களின் உழைப்பையும் வேளாண்மையின் பெருமையையும் போற்றும் 'ஏர்முனைக்கு நேர் இங்கே எதுவுமே இல்லை' மற்றும் 'மணப்பாறை மாடு கட்டி மாயவரம் ஏரு பூட்டி' ஆகிய புகழ்பெற்ற பாடல்களை அ.மருதகாசி இயற்றியுள்ளார்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":873,"subject":"tamil","testNumber":9,"question":"பாரதிதாசனின் மாணவரான கவிஞர் தமிழ்ஒளியின் இயற்பெயர் மற்றும் அவர் இயற்றிய நூல்களின் சரியான தொகுப்பு எது?","options":["விஜயரங்கம்; நிலைபெற்ற சிலை, வீராயி, மே தினமே வருக","அரங்கசாமி; தமிழச்சி, கொடிமுல்லை, தொடுவானம்","இராசகோபாலன்; தேன்மழை, துறைமுகம், சுவரும் சுண்ணாம்பும்","துரைராசு; பூங்கொடி, வீரகாவியம், காவியப் பாவை"],"correctAnswer":0,"explanation":"கவிஞர் தமிழ்ஒளியின் இயற்பெயர் விஜயரங்கம் ஆகும். பாரதிதாசனின் மாணவரான இவர் நிலைபெற்ற சிலை, வீராயி, கவிஞனின் காதல், மே தினமே வருக, கண்ணப்பன் கிளிகள், மாதவி காவியம், குருவிப்பட்டி முதலிய நூல்களை இயற்றியுள்ளார்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":874,"subject":"tamil","testNumber":9,"question":"\"மொட்டைக் கிளையொடு நின்று தினம்பெரு மூச்சு விடும்மரமே\" எனத் தொடங்கும் 'பட்டமரம்' என்ற கவிதையைப் படைத்தவர் யார்?","options":["முடியரசன்","தமிழ்ஒளி","சுரதா","வாணிதாசன்"],"correctAnswer":1,"explanation":"மரம் செடி கொடிகளைப் பாதுகாக்க வேண்டிய அவசியத்தையும் இயற்கை அழிவின் சோகத்தையும் உணர்த்தும் 'பட்டமரம்' என்ற கவிதையைப் படைத்தவர் கவிஞர் தமிழ்ஒளி ஆவார்.","difficulty":"hard","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":875,"subject":"tamil","testNumber":9,"question":"சிறுவர்களுக்காக எளிய, இனிய பாடல்களைப் படைத்ததால் 'குழந்தைக் கவிஞர்' எனப் போற்றப்படுபவர் யார்?","options":["கவிமணி தேசிக விநாயகம் பிள்ளை","பட்டுக்கோட்டை கல்யாணசுந்தரம்","அழ.வள்ளியப்பா","வாணிதாசன்"],"correctAnswer":2,"explanation":"புதுக்கோட்டை மாவட்டம் இராயவரத்தில் பிறந்த அழ.வள்ளியப்பா, சிறுவர் இலக்கியத்திற்கு ஆற்றிய அளப்பரிய பணியால் 'குழந்தைக் கவிஞர்' எனப் போற்றப்படுகிறார். இவர் 'குழந்தை எழுத்தாளர் சங்கத்தை' நிறுவினார்.","difficulty":"easy","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":876,"subject":"tamil","testNumber":9,"question":"'மலரும் உள்ளம்', 'பாட்டிலே காந்தி கதை', 'ஈசாப் கதைப் பாடல்கள்' ஆகிய சிறுவர் இலக்கிய நூல்களை இயற்றியவர் யார்?","options":["தமிழ்ஒளி","அழ.வள்ளியப்பா","நாமக்கல் கவிஞர்","கவிமணி தேசிக விநாயகம் பிள்ளை"],"correctAnswer":1,"explanation":"மலரும் உள்ளம் (இரு தொகுதிகள்), சிரிக்கும் பூக்கள், பாலர் பாடல்கள், பாட்டிலே காந்தி கதை, ஈசாப் கதைப் பாடல்கள், பிள்ளைப் பருவத்திலே ஆகியன குழந்தைக் கவிஞர் அழ.வள்ளியப்பா இயற்றிய நூல்களாகும்.","difficulty":"medium","topic":"மரபுக் கவிஞர்கள் & திரையிசைக் கவிஞர்கள்"},{"id":877,"subject":"tamil","testNumber":9,"question":"'தமிழ்ப் புதுக்கவிதையின் தந்தை' எனப் போற்றப்படும் ந.பிச்சமூர்த்தியின் 'காதல்' என்ற புதுக்கவிதை எந்த இதழில் வெளிவந்தது?","options":["கசடதபற","எழுத்து","மணிக்கொடி","வானம்பாடி"],"correctAnswer":2,"explanation":"கும்பகோணத்தில் பிறந்த ந.பிச்சமூர்த்தி (இயற்பெயர்: ந.வேங்கட மகாலிங்கம்) 'தமிழ்ப் புதுக்கவிதையின் தந்தை' எனப் போற்றப்படுகிறார். 1934-ஆம் ஆண்டு 'மணிக்கொடி' இதழில் வெளிவந்த இவரது 'காதல்' என்ற கவிதை புதுக்கவிதை வளர்ச்சிக்கு அடிகோலியது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":878,"subject":"tamil","testNumber":9,"question":"'காட்டு வாத்து', 'வழித்துணை', 'கிளிக்கூண்டு', 'குயிலின் சுருதி' ஆகிய புதுக்கவிதை நூல்களை இயற்றியவர் யார்?","options":["சி.மணி","பசுவய்யா","ந.பிச்சமூர்த்தி","சி.சு.செல்லப்பா"],"correctAnswer":2,"explanation":"காட்டு வாத்து, வழித்துணை, கிளிக்கூண்டு, குயிலின் சுருதி, பூக்காரி ஆகிய புதுக்கவிதைத் தொகுப்புகளை இயற்றியவர் ந.பிச்சமூர்த்தி ஆவார். இவர் 'பிக்ஷு', 'ரேவதி' ஆகிய புனைபெயர்களிலும் எழுதியுள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":879,"subject":"tamil","testNumber":9,"question":"1959-ஆம் ஆண்டு 'எழுத்து' என்னும் சிற்றிதழைத் தொடங்கித் தமிழில் புதுக்கவிதை இயக்கத்தை வளர்த்தெடுத்தவர் யார்?","options":["ந.பிச்சமூர்த்தி","சி.சு.செல்லப்பா","சிற்பி பாலசுப்பிரமணியம்","மீரா"],"correctAnswer":1,"explanation":"சி.சு.செல்லப்பா 1959-ஆம் ஆண்டு 'எழுத்து' என்ற சிற்றிதழைத் தொடங்கிப் புதுக்கவிதைக்கும் நவீன இலக்கியத் திறனாய்வுக்கும் பெரும் தளத்தை அமைத்துத் தந்தார்.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":880,"subject":"tamil","testNumber":9,"question":"தமிழின் முதல் புதுக்கவிதைத் தொகுப்பான 'புதுக்குரல்கள்' நூலைப் பதிப்பித்ததோடு, 'சுதந்திர தாகம்' புதினத்திற்காக 2001-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றவர் யார்?","options":["கலாப்ரியா","சி.சு.செல்லப்பா","ந.பிச்சமூர்த்தி","சுந்தர ராமசாமி"],"correctAnswer":1,"explanation":"சி.சு.செல்லப்பா 1962-இல் 'புதுக்குரல்கள்' என்ற முதல் புதுக்கவிதைத் தொகுப்பை வெளியிட்டார். மேலும் 'வாடிவாசல்', 'ஜீவனாம்சம்' ஆகிய புகழ்பெற்ற படைப்புகளையும், 2001-இல் சாகித்திய அகாதெமி விருது பெற்ற 'சுதந்திர தாகம்' புதினத்தையும் எழுதியுள்ளார்.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":881,"subject":"tamil","testNumber":9,"question":"\"சிறகிலிருந்து பிரிந்த இறகு ஒன்று காற்றின் தீராத பக்கங்களில் ஒரு பறவையின் வாழ்வை எழுதிச் செல்கிறது\" என்ற புகழ்பெற்ற புதுக்கவிதையை இயற்றியவர் யார்?","options":["பசுவய்யா","சி.மணி","தருமு சிவராமு (பிரமிள்)","ஞானக்கூத்தன்"],"correctAnswer":2,"explanation":"இலங்கையில் பிறந்து 'எழுத்து' இதழ் வழியே தமிழுக்குப் புதிய படிமங்களைத் தந்த தருமு சிவராமு (பிரமிள்; இயற்பெயர்: சிவராமலிங்கம்) இயற்றிய 'காவியம்' என்ற கவிதையில் இவ்வரிகள் இடம்பெற்றுள்ளன. 'கண்ணாடியுள்ளிருந்து', 'கைப்பிடியளவு கடல்' ஆகியன இவரது தொகுப்புகள் ஆகும்.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":882,"subject":"tamil","testNumber":9,"question":"'நடுநிசி நாய்கள்', 'யாரோ ஒருவனுக்காக' ஆகிய புதுக்கவிதைத் தொகுப்புகளை 'பசுவய்யா' என்ற புனைபெயரில் எழுதிய புகழ்பெற்ற தமிழ் எழுத்தாளர் யார்?","options":["கி.ராஜநாராயணன்","சுந்தர ராமசாமி","தி.ஜானகிராமன்","ஜெயகாந்தன்"],"correctAnswer":1,"explanation":"'ஒரு புளியமரத்தின் கதை' போன்ற புகழ்பெற்ற புதினங்களை எழுதிய சுந்தர ராமசாமி, 'பசுவய்யா' என்ற புனைபெயரில் 'நடுநிசி நாய்கள்', 'யாரோ ஒருவனுக்காக', '107 கவிதைகள்' ஆகிய புதுக்கவிதைத் தொகுப்புகளைப் படைத்துள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":883,"subject":"tamil","testNumber":9,"question":"'நெருஞ்சி', 'சுடுபூக்கள்', 'தீபாவளிப் பகல்', 'கொடிவிளக்கு' ஆகிய புதுக்கவிதைத் தொகுப்புகளை இயற்றிய முன்னோடிப் பெண் கவிஞர் யார்?","options":["இரா.மீனாட்சி","ஆண்டாள் பிரியதர்ஷினி","சல்மா","திலகவதி"],"correctAnswer":0,"explanation":"1970-களில் புதுக்கவிதை எழுதிய முன்னோடிப் பெண் கவிஞர்களுள் குறிப்பிடத்தக்கவரான இரா.மீனாட்சி நெருஞ்சி, சுடுபூக்கள், தீபாவளிப் பகல், மறுபயணம், வாசனைப் புல், உதய நகரிலிருந்து, கொடிவிளக்கு ஆகிய கவிதைத் தொகுப்புகளை இயற்றியுள்ளார்.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":884,"subject":"tamil","testNumber":9,"question":"'நடை' என்ற சிற்றிதழை நடத்தியதோடு, 'வரும் போகும்', 'ஒளிச்சேர்க்கை', 'யாப்பும் கவிதையும்' ஆகிய நூல்களை எழுதிய புதுக்கவிஞர் யார்?","options":["சி.மணி","ஞானக்கூத்தன்","கல்யாண்ஜி","கலாப்ரியா"],"correctAnswer":0,"explanation":"இயற்பெயர் சி.பழனிசாமி கொண்ட சி.மணி 'நடை' என்னும் சிற்றிதழை நடத்தினார். 'வரும் போகும்', 'ஒளிச்சேர்க்கை', 'இதுவரை' ஆகிய கவிதைத் தொகுப்புகளையும் 'யாப்பும் கவிதையும்' என்ற ஆய்வு நூலையும் படைத்துள்ளார்.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":885,"subject":"tamil","testNumber":9,"question":"சிற்பி பாலசுப்பிரமணியத்திற்கு 2002-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றுத் தந்த கவிதை நூல் எது?","options":["ஒரு கிராமத்து நதி","சர்ப்பயாகம்","ஒளிப்பறவை","நிலவுப்பூ"],"correctAnswer":0,"explanation":"'வானம்பாடி' கவிதை இயக்கத்தின் முன்னோடிகளுள் ஒருவரான சிற்பி பாலசுப்பிரமணியம் எழுதிய 'ஒரு கிராமத்து நதி' என்னும் கவிதைத் தொகுப்பிற்கு 2002-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":886,"subject":"tamil","testNumber":9,"question":"மலையாளப் புதினமான 'அக்னி சாட்சி'யைத் தமிழில் மொழிபெயர்த்தமைக்காகவும் (2001) கவிதைக்காகவும் என இருமுறை சாகித்திய அகாதெமி விருது பெற்ற கவிஞர் யார்?","options":["ஈரோடு தமிழன்பன்","மு.மேத்தா","சிற்பி பாலசுப்பிரமணியம்","அப்துல் ரகுமான்"],"correctAnswer":2,"explanation":"சிற்பி பாலசுப்பிரமணியம் மலையாளத்திலிருந்து 'அக்னி சாட்சி' என்ற புதினத்தைத் தமிழில் மொழிபெயர்த்ததற்காக 2001-ஆம் ஆண்டும், 'ஒரு கிராமத்து நதி' கவிதை நூலுக்காக 2002-ஆம் ஆண்டும் என இருமுறை சாகித்திய அகாதெமி விருது பெற்றுள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":887,"subject":"tamil","testNumber":9,"question":"கவிஞர் மு.மேத்தாவுக்கு 2006-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றுத் தந்த புதுக்கவிதை நூல் எது?","options":["ஆகாயத்துக்கு அடுத்த வீடு","ஊர்வலம்","கண்ணீர்ப் பூக்கள்","மகுட நிலா"],"correctAnswer":0,"explanation":"வானம்பாடிக் கவிஞர்களுள் ஒருவரான மு.மேத்தா எழுதிய 'ஆகாயத்துக்கு அடுத்த வீடு' என்னும் புதுக்கவிதைத் தொகுப்பிற்கு 2006-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":888,"subject":"tamil","testNumber":9,"question":"'கண்ணீர்ப் பூக்கள்', 'ஊர்வலம்', 'சோழ நிலா' ஆகிய நூல்களை இயற்றிய கவிஞர் யார்?","options":["மீரா","மு.மேத்தா","தாராபாரதி","அப்துல் ரகுமான்"],"correctAnswer":1,"explanation":"புதுக்கவிதையை மக்கள் மயமாக்கிய கவிஞர் மு.மேத்தாவின் முதல் கவிதைத் தொகுப்பு 'கண்ணீர்ப் பூக்கள்' ஆகும். இவரது 'ஊர்வலம்' நூல் தமிழக அரசுப் பரிசையும், 'சோழ நிலா' என்ற புதினம் பரவலான பாராட்டையும் பெற்றன.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":889,"subject":"tamil","testNumber":9,"question":"2004-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்ற 'வணக்கம் வள்ளுவ' என்ற கவிதை நூலின் ஆசிரியர் யார்?","options":["ஈரோடு தமிழன்பன்","வைரமுத்து","அப்துல் ரகுமான்","சிற்பி பாலசுப்பிரமணியம்"],"correctAnswer":0,"explanation":"ஈரோடு மாவட்டம் சென்னிமலையில் பிறந்த ஈரோடு தமிழன்பன் (இயற்பெயர்: ந.ஜெகதீசன்) எழுதிய 'வணக்கம் வள்ளுவ' என்ற கவிதை நூலுக்கு 2004-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":890,"subject":"tamil","testNumber":9,"question":"ஹைக்கூ, சென்ரியு, லிமரைக்கூ ஆகிய புதுவடிவங்களில் கவிதை படைத்து, 'சூரியப் பிறைகள்', 'ஒரு வண்டியும் சென்ரியுவும்' ஆகிய நூல்களை இயற்றியவர் யார்?","options":["ஈரோடு தமிழன்பன்","தாராபாரதி","மீரா","அப்துல் ரகுமான்"],"correctAnswer":0,"explanation":"மரபுக்கவிதை, புதுக்கவிதை, ஹைக்கூ, சென்ரியு மற்றும் லிமரைக்கூ எனப் பல வடிவங்களில் கவிதை படைத்த ஈரோடு தமிழன்பன் 'சூரியப் பிறைகள்', 'ஒரு வண்டியும் சென்ரியுவும்', 'தோணி வருகிறது', 'தமிழோவியம்' முதலிய நூல்களை இயற்றியுள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":891,"subject":"tamil","testNumber":9,"question":"'கவிக்கோ' எனப் போற்றப்படும் அப்துல் ரகுமானுக்கு 1999-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றுத் தந்த நூல் எது?","options":["ஆலாபனை","நேயர் விருப்பம்","சுட்டுவிரல்","பால்வீதி"],"correctAnswer":0,"explanation":"வானம்பாடி இயக்கக் கவிஞரும் ஹைக்கூ, கஜல் வடிவங்களைத் தமிழில் வளப்படுத்தியவருமான கவிக்கோ அப்துல் ரகுமான் இயற்றிய 'ஆலாபனை' என்னும் கவிதைத் தொகுப்பிற்கு 1999-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":892,"subject":"tamil","testNumber":9,"question":"'பால்வீதி', 'நேயர் விருப்பம்', 'சுட்டுவிரல்', 'பித்தன்', 'கரைகளே நதியாவதில்லை' ஆகிய நூல்களின் ஆசிரியர் யார்?","options":["வைரமுத்து","ஈரோடு தமிழன்பன்","மு.மேத்தா","அப்துல் ரகுமான்"],"correctAnswer":3,"explanation":"'பால்வீதி' என்பது கவிக்கோ அப்துல் ரகுமானின் முதல் கவிதைத் தொகுப்பாகும். நேயர் விருப்பம், சுட்டுவிரல், பித்தன், ஆலாபனை, கரைகளே நதியாவதில்லை, மின்மினிகளால் ஒரு கடிதம் ஆகியன இவரது புகழ்பெற்ற படைப்புகள் ஆகும்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":893,"subject":"tamil","testNumber":9,"question":"தி.க.சோமசுந்தரம் என்ற இயற்பெயர் கொண்டு 'வெள்ளம்', 'எட்டயபுரம்', 'மற்றாங்கே', 'சுயம்வரம்' ஆகிய புதுக்கவிதைத் தொகுப்புகளைப் படைத்தவர் யார்?","options":["சி.மணி","கலாப்ரியா","ஞானக்கூத்தன்","கல்யாண்ஜி"],"correctAnswer":1,"explanation":"திருநெல்வேலியைச் சேர்ந்த தி.க.சோமசுந்தரம் 'கலாப்ரியா' என்ற புனைபெயரில் வெள்ளம், தீர்த்த யாத்திரை, மற்றாங்கே, எட்டயபுரம், சுயம்வரம், உலகெல்லாம் சூரியன் ஆகிய புகழ்பெற்ற புதுக்கவிதைத் தொகுப்புகளைப் படைத்துள்ளார்.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":894,"subject":"tamil","testNumber":9,"question":"'வண்ணதாசன்' என்ற பெயரில் சிறுகதைகள் எழுதுபவரும், 'புலரி', 'முன்பின்', 'ஆதி', 'அந்நியமற்ற நதி' ஆகிய கவிதைத் தொகுப்புகளைப் படைத்தவருமான கவிஞர் யார்?","options":["கலாப்ரியா","பசுவய்யா","கல்யாண்ஜி","தருமு சிவராமு"],"correctAnswer":2,"explanation":"ச.கல்யாணசுந்தரம் என்ற இயற்பெயர் கொண்ட இவர், 'கல்யாண்ஜி' என்ற பெயரில் புலரி, முன்பின், ஆதி, அந்நியமற்ற நதி, மணல் உள்ள ஆறு ஆகிய கவிதைத் தொகுப்புகளையும், 'வண்ணதாசன்' என்ற பெயரில் 2016 சாகித்திய அகாதெமி விருது பெற்ற 'ஒரு சிறு இசை' உள்ளிட்ட சிறுகதைகளையும் எழுதியுள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":895,"subject":"tamil","testNumber":9,"question":"'அன்று வேறு கிழமை', 'சூரியனுக்குப் பின்பக்கம்' ஆகிய தொகுப்புகளை இயற்றி, \"எனக்கும் தமிழ்தான் மூச்சு; ஆனால் பிறர்மேல் அதை விடமாட்டேன்\" என்று அங்கதக் கவிதை எழுதியவர் யார்?","options":["ந.பிச்சமூர்த்தி","மீரா","ஞானக்கூத்தன்","சி.மணி"],"correctAnswer":2,"explanation":"அரங்கநாதன் என்ற இயற்பெயர் கொண்ட புதுக்கவிஞர் ஞானக்கூத்தன் 'அன்று வேறு கிழமை', 'சூரியனுக்குப் பின்பக்கம்', 'கடற்கரையில் சில மரங்கள்' ஆகிய தொகுப்புகளைப் படைத்துள்ளார். 'எனக்கும் தமிழ்தான் மூச்சு; ஆனால் பிறர்மேல் அதை விடமாட்டேன்' என்ற புகழ்பெற்ற அங்கத வரி இவருடையதே.","difficulty":"hard","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":896,"subject":"tamil","testNumber":9,"question":"'கவிஞாயிறு' எனப் போற்றப்படும் தாராபாரதி இயற்றிய நூல்களின் சரியான தொகுப்பு எது?","options":["பால்வீதி, ஆலாபனை, நேயர் விருப்பம்","புதிய விடியல்கள், இது எங்கள் கிழக்கு, விரல்நுனி வெளிச்சங்கள்","கண்ணீர்ப் பூக்கள், ஊர்வலம், ஆகாயத்துக்கு அடுத்த வீடு","ஒளிப்பறவை, சர்ப்பயாகம், ஒரு கிராமத்து நதி"],"correctAnswer":1,"explanation":"'கவிஞாயிறு' தாராபாரதி (இயற்பெயர்: இராதாகிருஷ்ணன்) இயற்றிய புகழ்பெற்ற கவிதை நூல்கள் புதிய விடியல்கள், இது எங்கள் கிழக்கு, விரல்நுனி வெளிச்சங்கள், பூமியைத் திறக்கும் பொன்சாவி, இன்னொரு சிகரம் ஆகியனவாகும்.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":897,"subject":"tamil","testNumber":9,"question":"\"வெறுங்கை என்பது மூடத்தனம் – உன் விரல்கள் பத்தும் மூலதனம்\" மற்றும் \"தெய்வ வள்ளுவன் நெய்த குறள்தான் தேசம் உடுத்திய நூலாடை\" என்ற வரிகளை இயற்றியவர் யார்?","options":["மு.மேத்தா","தாராபாரதி","வைரமுத்து","ஈரோடு தமிழன்பன்"],"correctAnswer":1,"explanation":"தன்னம்பிக்கை ஊட்டும் 'வெறுங்கை என்பது மூடத்தனம் – உன் விரல்கள் பத்தும் மூலதனம்' என்ற வரிகளையும், 'பாரதம் அன்றைய நாற்றங்கால்' என்ற பாடலில் வரும் 'தெய்வ வள்ளுவன் நெய்த குறள்தான் தேசம் உடுத்திய நூலாடை' என்ற வரிகளையும் இயற்றியவர் தாராபாரதி ஆவார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":898,"subject":"tamil","testNumber":9,"question":"கவிப்பேரரசு வைரமுத்துவுக்கு 2003-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது பெற்றுத் தந்த புதினம் எது?","options":["கருவாச்சி காவியம்","தண்ணீர் தேசம்","கள்ளிக்காட்டு இதிகாசம்","மூன்றாம் உலகப்போர்"],"correctAnswer":2,"explanation":"வைகை அணை கட்டப்பட்டபோது இடம்பெயர்ந்த கிராம மக்களின் வாழ்வியலையும் வலியையும் சித்தரிக்கும் 'கள்ளிக்காட்டு இதிகாசம்' என்ற புதினத்திற்காகக் கவிப்பேரரசு வைரமுத்துவுக்கு 2003-ஆம் ஆண்டு சாகித்திய அகாதெமி விருது வழங்கப்பட்டது.","difficulty":"easy","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":899,"subject":"tamil","testNumber":9,"question":"'வைகறை மேகங்கள்', 'திருத்தி எழுதிய தீர்ப்புகள்', 'இன்னொரு தேசிய கீதம்', 'கவிராஜன் கதை' ஆகிய கவிதை நூல்களைப் படைத்தவர் யார்?","options":["வைரமுத்து","மு.மேத்தா","அப்துல் ரகுமான்","சிற்பி பாலசுப்பிரமணியம்"],"correctAnswer":0,"explanation":"தேனி மாவட்டம் மெட்டூரில் பிறந்த கவிப்பேரரசு வைரமுத்து 'வைகறை மேகங்கள்' (முதல் கவிதைத் தொகுப்பு), திருத்தி எழுதிய தீர்ப்புகள், இன்னொரு தேசிய கீதம், கவிராஜன் கதை (பாரதியார் வரலாறு), கொடிமரத்தின் வேர்கள் ஆகிய கவிதை நூல்களை இயற்றியுள்ளார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"},{"id":900,"subject":"tamil","testNumber":9,"question":"'ஊசிகள்', 'கனவுகள் + கற்பனைகள் = காகிதங்கள்' ஆகிய புதுக்கவிதை நூல்களை இயற்றியதோடு, 'அன்னம் விடு தூது' என்னும் இலக்கிய இதழை நடத்திய கவிஞர் யார்?","options":["சி.சு.செல்லப்பா","சி.மணி","சிற்பி பாலசுப்பிரமணியம்","மீரா"],"correctAnswer":3,"explanation":"மீ.இராசேந்திரன் என்ற இயற்பெயர் கொண்ட கவிஞர் மீரா 'ஊசிகள்', 'கனவுகள் + கற்பனைகள் = காகிதங்கள்', 'மூன்றும் ஆறும்', 'குக்கூ' ஆகிய நூல்களை இயற்றியுள்ளார். இவர் 'அன்னம் விடு தூது' என்ற இலக்கிய இதழையும் அன்னம் பதிப்பகத்தையும் நடத்தினார்.","difficulty":"medium","topic":"புதுக்கவிதை & ஹைக்கூ கவிஞர்கள்"}]);
